    public function rejectReasonSubmit(Request $request)
    {
        $shipper_id = $request->shipper_id;
        $reject_reason = $request->rejected_reason;
        $user = User::find($shipper_id);
        if($user->status != 3){
            $user->status = 5;
        }
        if($user->rate_type_id_status == 1){
            $user->rate_type_id_status = 2;
        }
        $user->rejected_reason = $reject_reason;
        $user->rate_status = 2;
        $user->rates_rejected_by = Auth::id();
        $user->rates_rejected_at = Carbon::now();
        $user->save();
        NotificationsController::send(64, $shipper_id );
        return ['success' => 'Rates has been rejected!'];
    }

    public function rate_type_submit(Request $request){
        $rate_type_id = $request->rate_type;
        $shipper_id = $request->shipper_id;
        if($shipper_id && $rate_type_id){
            $shipper = User::find($shipper_id);
            if($shipper){
                $shipper->corporate_rate_type_id = $rate_type_id;
                $shipper->save();
                return response()->json(['status' => 1, 'success' => 'Rate type updated successfully!']);
            }
            return response()->json(['status' => 0, 'error' => 'Shipper not found!']);
        }
        return response()->json(['status' => 0, 'error' => 'Rate type or shipper not selected!']);
    }

